return ['project-id-version'=>'WPOptimizing','pot-creation-date'=>'2026-10-22 14:54+0200','po-revision-date'=>'2026-02-19 09:32+0000','last-translator'=>'Art Project Group','language-team'=>'Español','language'=>'es_ES','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','plural-forms'=>'nplurals=2; plural=(n != 1);','messages'=>['Table'=>'Tabla','Option'=>'Opción','Post meta'=>'Meta de entrada','User meta'=>'Meta de usuario','Cron event'=>'Evento de cron','Plugin'=>'Plugin','Theme'=>'Tema','File'=>'Archivo','The update could not be downloaded: the update token could not be obtained.'=>'No se pudo descargar la actualización: no se pudo obtener el token de actualización.','The update could not be downloaded: a temporary file could not be created.'=>'No se pudo descargar la actualización: no se pudo crear un fichero temporal.','The update could not be downloaded: the repository answered with HTTP %d.'=>'No se pudo descargar la actualización: el repositorio respondió con HTTP %d.','Some kind of error occurred while trying to check the plugin license key.'=>'Se ha producido algún tipo de error al intentar comprobar la licencia del plugin.','Your license key has been activated!'=>'¡Tu licencia ha sido activada!','Your license key has been deactivated!'=>'¡Tu licencia ha sido desactivada!','Scan interrupted. Please try again.'=>'Análisis interrumpido. Inténtalo de nuevo.','This scan was bounded, so this list may include media that is actually in use. Select the items you have checked yourself instead.'=>'Este análisis fue acotado, así que esta lista puede incluir medios que sí se están usando. Selecciona en su lugar los elementos que hayas comprobado tú.','Object cache'=>'Caché de objetos','Available in WPOptimizing Pro.'=>'Disponible en WPOptimizing Pro.','Pro feature — click to learn more'=>'Función Pro: haz clic para saber más','feature badge' . "\4" . 'Pro'=>'Pro','Save as PD